import type { Spellbook } from '@/core/rules/types';
import officialSpellbooksJson from './officialSpellbooks.json';

// Generated by `npm run data` from the module's official spellbooks: mage id to card id counts.
const officialCounts: Record<string, Spellbook['counts']> = officialSpellbooksJson;

/** The mage's official spellbook as a new object, or null when there is no mage or it has none. */
export const officialSpellbook = (mageId: string | null): Spellbook | null => {
  if (mageId === null) {
    return null;
  }

  const counts = Object.hasOwn(officialCounts, mageId) ? officialCounts[mageId] : undefined;

  if (counts === undefined) {
    return null;
  }

  return { mageId, counts: { ...counts } };
};
